const char ai_gesture_html[] = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>AI Cyberpunk Hand Tracking</title>\n    <!-- MediaPipe dependencies -->\n    <script src=\"https://cdn.jsdelivr.net/npm/@mediapipe/camera_utils/camera_utils.js\" crossorigin=\"anonymous\"></script>\n    <script src=\"https://cdn.jsdelivr.net/npm/@mediapipe/control_utils/control_utils.js\" crossorigin=\"anonymous\"></script>\n    <script src=\"https://cdn.jsdelivr.net/npm/@mediapipe/drawing_utils/drawing_utils.js\" crossorigin=\"anonymous\"></script>\n    <script src=\"https://cdn.jsdelivr.net/npm/@mediapipe/hands/hands.js\" crossorigin=\"anonymous\"></script>\n    \n    <style>\n        @import url('https://fonts.googleapis.com/css2?family=Share+Tech+Mono&display=swap');\n        \n        body {\n            margin: 0;\n            padding: 0;\n            background-color: #050a0f;\n            color: #ffffff;\n            font-family: 'Share Tech Mono', monospace;\n            overflow: hidden;\n            display: flex;\n            justify-content: center;\n            align-items: center;\n            height: 100vh;\n        }\n\n        .container {\n            position: relative;\n            width: 800px;\n            height: 600px;\n            border: 2px solid #ffffff;\n            box-shadow: 0 0 20px rgba(255, 255, 255, 0.3), inset 0 0 20px rgba(255, 255, 255, 0.3);\n            background: rgba(10, 10, 15, 0.8);\n        }\n\n        .corner {\n            position: absolute;\n            width: 30px;\n            height: 30px;\n            border-color: #ffffff;\n            border-style: solid;\n        }\n\n        .corner-tl { top: -2px; left: -2px; border-width: 4px 0 0 4px; }\n        .corner-tr { top: -2px; right: -2px; border-width: 4px 4px 0 0; }\n        .corner-bl { bottom: -2px; left: -2px; border-width: 0 0 4px 4px; }\n        .corner-br { bottom: -2px; right: -2px; border-width: 0 4px 4px 0; }\n\n        video, img, canvas {\n            position: absolute;\n            top: 0;\n            left: 0;\n            width: 100%;\n            height: 100%;\n            object-fit: cover;\n        }\n\n        .hud-overlay {\n            position: absolute;\n            top: 0; left: 0; right: 0; bottom: 0;\n            pointer-events: none;\n            z-index: 10;\n            background: \n                linear-gradient(rgba(255,255,255,0.05) 1px, transparent 1px),\n                linear-gradient(90deg, rgba(255,255,255,0.05) 1px, transparent 1px);\n            background-size: 20px 20px;\n        }\n\n        .info-panel {\n            position: absolute;\n            top: 20px;\n            left: 20px;\n            z-index: 20;\n            background: rgba(20, 25, 30, 0.7);\n            border: 1px solid #ffffff;\n            padding: 15px;\n            backdrop-filter: blur(5px);\n        }\n\n        .status { margin-bottom: 10px; font-size: 1.2em; }\n        .status span { color: #ff6666; font-weight: bold; animation: pulse 1s alternate infinite; }\n        \n        .gesture-box {\n            position: absolute;\n            bottom: 20px;\n            right: 20px;\n            z-index: 20;\n            border: 1px solid #ff6666;\n            padding: 10px 20px;\n            background: rgba(30, 10, 15, 0.7);\n            text-align: center;\n        }\n\n        .gesture-text {\n            font-size: 2em;\n            color: #ff6666;\n            text-transform: uppercase;\n            letter-spacing: 2px;\n            text-shadow: 0 0 10px #ff6666;\n        }\n\n        @keyframes pulse {\n            from { text-shadow: 0 0 5px #ffffff; }\n            to { text-shadow: 0 0 15px #ffffff, 0 0 25px #ffffff; }\n        }\n\n        .scanning-bar {\n            position: absolute;\n            top: 0; left: 0; width: 100%; height: 5px;\n            background: #ffffff;\n            box-shadow: 0 0 15px #ffffff;\n            animation: scan 3s linear infinite;\n            z-index: 5;\n            opacity: 0.5;\n        }\n\n        @keyframes scan {\n            0% { top: 0; opacity: 0; }\n            10% { opacity: 0.5; }\n            90% { opacity: 0.5; }\n            100% { top: 100%; opacity: 0; }\n        }\n    </style>\n</head>\n<body>\n\n    <div class=\"container\">\n        <div class=\"corner corner-tl\"></div>\n        <div class=\"corner corner-tr\"></div>\n        <div class=\"corner corner-bl\"></div>\n        <div class=\"corner corner-br\"></div>\n        \n        <!-- Stream from ESP32 -->\n        <img id=\"esp32_stream\" src=\"/stream\" crossorigin=\"anonymous\" style=\"display:none;\" />\n        \n        <canvas id=\"output_canvas\"></canvas>\n        <div class=\"scanning-bar\"></div>\n        <div class=\"hud-overlay\"></div>\n\n        <div class=\"info-panel\">\n            <div class=\"status\">AI CORE: <span style=\"color:#ffffff;\">ONLINE</span></div>\n            <div class=\"status\">TARGET: <span id=\"target_status\">SEARCHING...</span></div>\n            <div>SYS.FREQ: 160MHz (ESP32-S3)</div>\n            <div>NET: CINQ_LAP_HOTSPOT</div>\n        </div>\n\n        <div class=\"gesture-box\">\n            <div style=\"font-size:0.8em; color:#aaa;\">DETECTED GESTURE</div>\n            <div class=\"gesture-text\" id=\"gesture_result\">NONE</div>\n        </div>\n    </div>\n\n    <script>\n        const espStream = document.getElementById('esp32_stream');\n        const canvasElement = document.getElementById('output_canvas');\n        const canvasCtx = canvasElement.getContext('2d');\n        const gestureResult = document.getElementById('gesture_result');\n        const targetStatus = document.getElementById('target_status');\n\n        canvasElement.width = 800;\n        canvasElement.height = 600;\n\n        function onResults(results) {\n            canvasCtx.save();\n            canvasCtx.clearRect(0, 0, canvasElement.width, canvasElement.height);\n            // Draw the ESP32 stream to the canvas\n            canvasCtx.drawImage(results.image, 0, 0, canvasElement.width, canvasElement.height);\n            \n            if (results.multiHandLandmarks && results.multiHandLandmarks.length > 0) {\n                targetStatus.innerText = \"LOCKED\";\n                targetStatus.style.color = \"#ff6666\";\n\n                for (const landmarks of results.multiHandLandmarks) {\n                    drawConnectors(canvasCtx, landmarks, HAND_CONNECTIONS, {color: '#ffffff', lineWidth: 2});\n                    drawLandmarks(canvasCtx, landmarks, {color: '#ff6666', lineWidth: 1, radius: 3});\n                    \n                    // Simple gesture logic\n                    const thumbTip = landmarks[4];\n                    const indexTip = landmarks[8];\n                    const middleTip = landmarks[12];\n                    const ringTip = landmarks[16];\n                    const pinkyTip = landmarks[20];\n                    const wrist = landmarks[0];\n\n                    const isIndexUp = indexTip.y < landmarks[6].y;\n                    const isMiddleUp = middleTip.y < landmarks[10].y;\n                    const isRingUp = ringTip.y < landmarks[14].y;\n                    const isPinkyUp = pinkyTip.y < landmarks[18].y;\n\n                    if (isIndexUp && isMiddleUp && !isRingUp && !isPinkyUp) {\n                        gestureResult.innerText = \"PEACE (V)\";\n                    } else if (!isIndexUp && !isMiddleUp && !isRingUp && !isPinkyUp) {\n                        gestureResult.innerText = \"FIST\";\n                    } else if (isIndexUp && isMiddleUp && isRingUp && isPinkyUp) {\n                        gestureResult.innerText = \"OPEN HAND\";\n                    } else {\n                        gestureResult.innerText = \"TRACKING...\";\n                    }\n                }\n            } else {\n                targetStatus.innerText = \"SEARCHING...\";\n                targetStatus.style.color = \"#ffffff\";\n                gestureResult.innerText = \"NONE\";\n            }\n            canvasCtx.restore();\n        }\n\n        const hands = new Hands({locateFile: (file) => {\n            return `https://cdn.jsdelivr.net/npm/@mediapipe/hands/${file}`;\n        }});\n        \n        hands.setOptions({\n            maxNumHands: 2,\n            modelComplexity: 1,\n            minDetectionConfidence: 0.5,\n            minTrackingConfidence: 0.5\n        });\n        \n        hands.onResults(onResults);\n\n        let processing = false;\n        async function processFrame() {\n            if (!processing && espStream.complete && espStream.naturalHeight !== 0) {\n                processing = true;\n                await hands.send({image: espStream});\n                processing = false;\n            }\n            requestAnimationFrame(processFrame);\n        }\n\n        // Start processing once the image starts loading\n        espStream.onload = () => {\n            if (!processing) {\n                processFrame();\n            }\n        };\n        // Fallback in case onload doesn't fire continuously for MJPEG\n        processFrame();\n    </script>\n</body>\n</html>\n";
